translationEntries.originalText:
.caption {
				background-color: activecaption;
				color: captiontext;
				font-weight: bold;
				border: black solid 1px;
				width: 100%;
			}
			.entry {
				border-bottom: black solid 1px;
				width: 100%;
			}
			.value {
				text-align:right;
				font-family: georgia;
			}
